package com.flightbooking.ui;

import com.flightbooking.model.*;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableModel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class AdminPanel extends JPanel {
    private static final DateTimeFormatter DT=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
    private final AppFrame frame; private final Account account;
    private final JTable flights=Ui.table("Airline","Flight","From","To","Departure","Arrival","Seats E/B","Fare E/B");
    private final JTable bookings=Ui.table("Ref","Customer","Email","Flight","Route","Departure","Total","Status");
    private final JTable cancellationRequests=Ui.table("Request","Booking","Passenger","Email","Flight","Route","Departure","Requested","Status");
    private final JTextField userSearch=Ui.field(30);
    private final DefaultListModel<UserInfo> userSuggestionModel=new DefaultListModel<>();
    private final JList<UserInfo> userSuggestions=new JList<>(userSuggestionModel);
    private final JLabel userProfile=Ui.muted("Choose a passenger recommendation to view their profile and records.");
    private final JTable userBookings=Ui.table("Ref","Flight","Route","Departure","Total","Status","Cancellation");
    private final JTable userPasses=Ui.table("Ticket","Passenger","Flight","Airline","Destination","Departure","Seat / Class","Price","Booking");
    private java.util.List<Flight> flightRows=java.util.List.of(); private java.util.List<BookingSummary> bookingRows=java.util.List.of();
    private java.util.List<CancellationRequest> requestRows=java.util.List.of();
    private java.util.List<UserInfo> userRows=java.util.List.of();
    private UserInfo selectedUser;
    AdminPanel(AppFrame frame,Account account){this.frame=frame;this.account=account;setLayout(new BorderLayout());setBackground(Ui.PAPER);add(header(),BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.setFont(new Font("Segoe UI",Font.BOLD,13));tabs.addTab("Flights",flightTab());tabs.addTab("Bookings",bookingTab());tabs.addTab("Cancellation requests",cancellationTab());tabs.addTab("Users",usersTab());add(tabs,BorderLayout.CENTER);refreshAll();}
    private JPanel header(){JPanel bar=new JPanel(new BorderLayout());bar.setBackground(Ui.DARK);bar.setBorder(new EmptyBorder(14,25,14,25));JLabel logo=new JLabel("✈  SKYWARD   /   ADMIN");logo.setFont(new Font("Segoe UI",Font.BOLD,18));logo.setForeground(Ui.WHITE);bar.add(logo,BorderLayout.WEST);JPanel right=new JPanel(new FlowLayout(FlowLayout.RIGHT,10,0));right.setOpaque(false);JLabel signedIn=Ui.muted("Signed in as "+account.getName());signedIn.setForeground(new Color(209,213,219));right.add(signedIn);JButton out=Ui.button("Sign out",false);out.addActionListener(e->frame.signOut());right.add(out);bar.add(right,BorderLayout.EAST);return bar;}
    private JPanel flightTab(){JPanel p=tabBase();JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));actions.setOpaque(false);JButton add=Ui.button("Add flight",true),edit=Ui.button("Edit selected",false),delete=Ui.button("Delete selected",false),refresh=Ui.button("Refresh",false);actions.add(add);actions.add(edit);actions.add(delete);actions.add(refresh);p.add(actions,BorderLayout.NORTH);p.add(new JScrollPane(flights),BorderLayout.CENTER);add.addActionListener(e->editFlight(null));edit.addActionListener(e->{Flight f=selectedFlight();if(f!=null)editFlight(f);});delete.addActionListener(e->deleteFlight());refresh.addActionListener(e->refreshFlights());return p;}
    private JPanel bookingTab(){JPanel p=tabBase();JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));actions.setOpaque(false);JButton refresh=Ui.button("Refresh bookings",false),delete=Ui.button("Delete selected booking",false);actions.add(refresh);actions.add(delete);p.add(actions,BorderLayout.NORTH);p.add(new JScrollPane(bookings),BorderLayout.CENTER);refresh.addActionListener(e->{refreshBookings();refreshRequests();});delete.addActionListener(e->deleteSelectedBooking());return p;}
    private JPanel cancellationTab(){JPanel p=tabBase();JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,0));actions.setOpaque(false);JButton approve=Ui.button("Approve selected",true),decline=Ui.button("Decline selected",false),refresh=Ui.button("Refresh requests",false);actions.add(approve);actions.add(decline);actions.add(refresh);p.add(actions,BorderLayout.NORTH);p.add(new JScrollPane(cancellationRequests),BorderLayout.CENTER);approve.addActionListener(e->resolveRequest(true));decline.addActionListener(e->resolveRequest(false));refresh.addActionListener(e->refreshRequests());return p;}
    private JPanel usersTab(){
        JPanel p=tabBase();
        JPanel top=new JPanel(new BorderLayout(12,0));top.setOpaque(false);
        top.add(Ui.formField("Search passengers by name or email",userSearch),BorderLayout.CENTER);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));actions.setOpaque(false);
        JButton refresh=Ui.button("Refresh users",false),reset=Ui.button("Reset selected passenger password",true);actions.add(refresh);actions.add(reset);top.add(actions,BorderLayout.EAST);p.add(top,BorderLayout.NORTH);
        userSuggestions.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);userSuggestions.setFont(new Font("Segoe UI",Font.PLAIN,13));userSuggestions.setFixedCellHeight(38);userSuggestions.setBorder(new EmptyBorder(5,7,5,7));
        JScrollPane suggestionScroll=new JScrollPane(userSuggestions);suggestionScroll.setBorder(BorderFactory.createTitledBorder("Live recommendations"));suggestionScroll.setPreferredSize(new Dimension(300,400));
        JPanel details=new JPanel(new BorderLayout(0,10));details.setOpaque(false);userProfile.setForeground(Ui.INK);userProfile.setFont(new Font("Segoe UI",Font.PLAIN,13));userProfile.setBorder(new EmptyBorder(10,12,10,12));details.add(userProfile,BorderLayout.NORTH);
        JTabbedPane records=new JTabbedPane();records.addTab("Booking history",new JScrollPane(userBookings));records.addTab("Boarding passes",new JScrollPane(userPasses));details.add(records,BorderLayout.CENTER);
        JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,suggestionScroll,details);split.setResizeWeight(.30);split.setBorder(null);p.add(split,BorderLayout.CENTER);
        userSearch.getDocument().addDocumentListener(new DocumentListener(){public void insertUpdate(DocumentEvent e){filterUserSuggestions();}public void removeUpdate(DocumentEvent e){filterUserSuggestions();}public void changedUpdate(DocumentEvent e){filterUserSuggestions();}});
        userSuggestions.addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&userSuggestions.getSelectedValue()!=null)loadUserDetails(userSuggestions.getSelectedValue());});
        refresh.addActionListener(e->refreshUsers());reset.addActionListener(e->resetPassengerPassword());return p;
    }
    private JPanel tabBase(){JPanel p=new JPanel(new BorderLayout(0,13));p.setBackground(Ui.PAPER);p.setBorder(new EmptyBorder(20,24,24,24));return p;}
    private void refreshAll(){refreshFlights();refreshBookings();refreshRequests();refreshUsers();}
    private void refreshFlights(){try{flightRows=frame.flightDao().listAll();DefaultTableModel m=Ui.model(flights);m.setRowCount(0);DateTimeFormatter f=DateTimeFormatter.ofPattern("d MMM yyyy · HH:mm");for(Flight x:flightRows)m.addRow(new Object[]{x.getAirlineName(),x.getFlightNumber(),x.getDepartureCity(),x.getDestinationCity(),f.format(x.getDepartureTime()),f.format(x.getArrivalTime()),x.getEconomyAvailableSeats()+" / "+x.getBusinessAvailableSeats(),"₹"+x.getEconomyPrice()+" / ₹"+x.getBusinessPrice()});}catch(Exception ex){Ui.error(this,"Could not load flights.\n"+ex.getMessage());}}
    private void refreshBookings(){try{bookingRows=frame.bookingDao().all();DefaultTableModel m=Ui.model(bookings);m.setRowCount(0);DateTimeFormatter f=DateTimeFormatter.ofPattern("d MMM · HH:mm");for(BookingSummary b:bookingRows)m.addRow(new Object[]{"SB-"+b.getId(),b.getCustomerName(),b.getEmail(),b.getFlightNumber(),b.getDepartureCity()+" → "+b.getDestinationCity(),f.format(b.getDepartureTime()),"₹"+b.getTotal(),b.getStatus()});}catch(Exception ex){Ui.error(this,"Could not load bookings.\n"+ex.getMessage());}}
    private void refreshRequests(){try{requestRows=frame.bookingDao().cancellationRequests();DefaultTableModel m=Ui.model(cancellationRequests);m.setRowCount(0);DateTimeFormatter dt=DateTimeFormatter.ofPattern("d MMM yyyy · HH:mm");for(CancellationRequest r:requestRows)m.addRow(new Object[]{"CR-"+r.getId(),"SB-"+r.getBookingId(),r.getCustomerName(),r.getEmail(),r.getFlightNumber(),r.getDepartureCity()+" → "+r.getDestinationCity(),dt.format(r.getDepartureTime()),dt.format(r.getRequestedAt()),r.getRequestStatus()});}catch(Exception ex){Ui.error(this,"Could not load cancellation requests.\n"+ex.getMessage());}}
    private void refreshUsers(){try{userRows=frame.accountDao().listUsers();filterUserSuggestions();if(selectedUser!=null){UserInfo refreshed=userRows.stream().filter(u->u.getId()==selectedUser.getId()).findFirst().orElse(null);if(refreshed==null){selectedUser=null;clearUserDetails();}else loadUserDetails(refreshed);}}catch(Exception ex){Ui.error(this,"Could not load users.\n"+ex.getMessage());}}
    private void filterUserSuggestions(){
        String query=userSearch.getText().trim().toLowerCase(Locale.ROOT);userSuggestionModel.clear();int added=0;
        for(UserInfo user:userRows){String name=user.getName()==null?"":user.getName().toLowerCase(Locale.ROOT),email=user.getEmail()==null?"":user.getEmail().toLowerCase(Locale.ROOT),phone=user.getPhone()==null?"":user.getPhone().toLowerCase(Locale.ROOT);
            if(query.isEmpty()||name.contains(query)||email.contains(query)||phone.contains(query)){userSuggestionModel.addElement(user);if(++added>=50)break;}}
    }
    private void loadUserDetails(UserInfo user){
        selectedUser=user;userProfile.setText("<html><b>"+escapeHtml(user.getName())+"</b> &nbsp; · &nbsp; "+escapeHtml(user.getEmail())+" &nbsp; · &nbsp; "+escapeHtml(user.getPhone()==null?"No phone":user.getPhone())+" &nbsp; · &nbsp; User ID "+user.getId()+"</html>");
        try{
            DateTimeFormatter dt=DateTimeFormatter.ofPattern("d MMM yyyy · HH:mm");DefaultTableModel bm=Ui.model(userBookings);bm.setRowCount(0);
            for(BookingSummary b:frame.bookingDao().forUser(user.getId()))bm.addRow(new Object[]{"SB-"+b.getId(),b.getFlightNumber(),b.getDepartureCity()+" → "+b.getDestinationCity(),dt.format(b.getDepartureTime()),"₹"+b.getTotal(),b.getStatus(),b.getCancellationStatus()==null?"—":b.getCancellationStatus()});
            DefaultTableModel pm=Ui.model(userPasses);pm.setRowCount(0);
            for(BoardingPass pass:frame.bookingDao().boardingPassesForUser(user.getId()))pm.addRow(new Object[]{pass.getTicketNumber(),pass.getPassengerName(),pass.getFlightNumber(),pass.getAirline(),pass.getDestinationCity(),dt.format(pass.getDepartureTime()),pass.getSeatNumber()+" / "+pass.getCabinClass(),"₹"+pass.getTicketPrice(),"SB-"+pass.getBookingId()});
        }catch(Exception ex){Ui.error(this,"Could not load this passenger's booking details.\n"+ex.getMessage());}
    }
    private void clearUserDetails(){userProfile.setText("Choose a passenger recommendation to view their profile and records.");Ui.model(userBookings).setRowCount(0);Ui.model(userPasses).setRowCount(0);}
    private String escapeHtml(String text){return text==null?"":text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    private Flight selectedFlight(){int row=flights.getSelectedRow();if(row<0){Ui.info(this,"Select a flight first.");return null;}return flightRows.get(flights.convertRowIndexToModel(row));}
    private void deleteSelectedBooking(){int row=bookings.getSelectedRow();if(row<0){Ui.info(this,"Select a booking first.");return;}BookingSummary booking=bookingRows.get(bookings.convertRowIndexToModel(row));if("CONFIRMED".equals(booking.getStatus())){Ui.info(this,"Approve a cancellation first. That applies the time-based refund and releases the seats before deletion.");return;}String confirm="Permanently delete booking SB-"+booking.getId()+" and its passengers, tickets, payments, cancellation requests, and refund history?";if(JOptionPane.showConfirmDialog(this,confirm,"Delete booking",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)!=JOptionPane.YES_OPTION)return;try{frame.bookingDao().deleteBookingForAdmin(booking.getId());Ui.info(this,"Booking SB-"+booking.getId()+" was deleted.");refreshBookings();refreshRequests();refreshFlights();}catch(Exception ex){Ui.error(this,ex.getMessage());}}
    private void editFlight(Flight current){try{java.util.List<Airline> airlines=frame.flightDao().airlines();if(airlines.isEmpty()){Ui.error(this,"Add an airline row to the airlines table before creating flights.");return;}JComboBox<Airline> airline=new JComboBox<>(airlines.toArray(Airline[]::new));JTextField number=Ui.field(18),from=Ui.field(18),to=Ui.field(18),depart=Ui.field(18),arrive=Ui.field(18),economySeats=Ui.field(8),businessSeats=Ui.field(8),economyFare=Ui.field(10),businessFare=Ui.field(10);
            if(current!=null){for(int i=0;i<airline.getItemCount();i++)if(airline.getItemAt(i).getId()==current.getAirlineId())airline.setSelectedIndex(i);number.setText(current.getFlightNumber());from.setText(current.getDepartureCity());to.setText(current.getDestinationCity());depart.setText(DT.format(current.getDepartureTime()));arrive.setText(DT.format(current.getArrivalTime()));economySeats.setText(String.valueOf(current.getEconomyCapacity()));businessSeats.setText(String.valueOf(current.getBusinessCapacity()));economyFare.setText(current.getEconomyPrice().toPlainString());businessFare.setText(current.getBusinessPrice().toPlainString());}else{LocalDateTime base=LocalDateTime.now().plusDays(7).withSecond(0).withNano(0);depart.setText(DT.format(base));arrive.setText(DT.format(base.plusHours(2)));economySeats.setText("64");businessSeats.setText("36");economyFare.setText("4999.00");businessFare.setText("13747.25");}
            JPanel form=new JPanel(new GridLayout(0,2,10,9));form.add(Ui.formField("Airline",airline));form.add(Ui.formField("Flight number",number));form.add(Ui.formField("Departure city",from));form.add(Ui.formField("Destination city",to));form.add(Ui.formField("Departure (yyyy-MM-dd HH:mm)",depart));form.add(Ui.formField("Arrival (yyyy-MM-dd HH:mm)",arrive));form.add(Ui.formField("Economy seat capacity",economySeats));form.add(Ui.formField("Business seat capacity (six-seat rows)",businessSeats));form.add(Ui.formField("Economy ticket price",economyFare));form.add(Ui.formField("Business ticket price (2.5×–3×)",businessFare));int result=JOptionPane.showConfirmDialog(this,new JScrollPane(form),current==null?"Add flight":"Edit flight",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(result!=JOptionPane.OK_OPTION)return;
            LocalDateTime d=LocalDateTime.parse(depart.getText().trim(),DT),a=LocalDateTime.parse(arrive.getText().trim(),DT);int economyCount=Integer.parseInt(economySeats.getText().trim()),businessCount=Integer.parseInt(businessSeats.getText().trim());BigDecimal economyPrice=new BigDecimal(economyFare.getText().trim()),businessPrice=new BigDecimal(businessFare.getText().trim());if(number.getText().isBlank()||from.getText().isBlank()||to.getText().isBlank()||from.getText().trim().equalsIgnoreCase(to.getText().trim())||economyCount<0||businessCount<0||!a.isAfter(d))throw new IllegalArgumentException("Check route, departure/arrival times, and non-negative cabin capacities.");frame.flightDao().save(current==null?0:current.getId(),((Airline)airline.getSelectedItem()).getId(),number.getText(),from.getText(),to.getText(),d,a,economyCount,businessCount,economyPrice,businessPrice);refreshFlights();
        }catch(Exception ex){Ui.error(this,"Flight was not saved. Check route/times, cabin capacity, fare ratio, and flight-number uniqueness.\n"+ex.getMessage());}}
    private void deleteFlight(){Flight f=selectedFlight();if(f==null)return;if(JOptionPane.showConfirmDialog(this,"Delete flight "+f.getFlightNumber()+"?","Confirm delete",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{frame.flightDao().delete(f.getId());refreshFlights();}catch(Exception ex){Ui.error(this,"This flight cannot be deleted while bookings refer to it.");}}
    private void cancelBooking(){int row=bookings.getSelectedRow();if(row<0){Ui.info(this,"Select a booking first.");return;}BookingSummary b=bookingRows.get(bookings.convertRowIndexToModel(row));if(!"PENDING".equals(b.getStatus())){Ui.info(this,"Only pending bookings can be cancelled here.");return;}try{if(frame.bookingDao().cancelPending(b.getId())){Ui.info(this,"Pending booking cancelled and seats released.");refreshBookings();refreshFlights();}}catch(Exception ex){Ui.error(this,"Could not cancel this booking.\n"+ex.getMessage());}}
    private void resolveRequest(boolean approve){int row=cancellationRequests.getSelectedRow();if(row<0){Ui.info(this,"Select a cancellation request first.");return;}CancellationRequest request=requestRows.get(cancellationRequests.convertRowIndexToModel(row));if(!"PENDING".equals(request.getRequestStatus())){Ui.info(this,"This request has already been reviewed.");return;}String action=approve?"Approve":"Decline";String detail=approve?"Approve cancellation for SB-"+request.getBookingId()+"? Seats will be released and any simulated payment marked refunded.":"Decline cancellation request CR-"+request.getId()+"?";if(JOptionPane.showConfirmDialog(this,detail,action+" request",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{frame.bookingDao().resolveCancellationRequest(request.getId(),account.getId(),approve);Ui.info(this,approve?"Request approved; booking cancelled and seats released.":"Request declined.");refreshRequests();refreshBookings();refreshFlights();}catch(Exception ex){Ui.error(this,"Could not review this request.\n"+ex.getMessage());}}
    private void resetPassengerPassword(){if(selectedUser==null){Ui.info(this,"Choose a passenger recommendation first.");return;}String email=selectedUser.getEmail();JPasswordField first=Ui.password(),confirm=Ui.password();JPanel form=new JPanel(new GridLayout(0,1,6,6));form.setBorder(new EmptyBorder(10,10,10,10));form.add(Ui.formField("New password (8+ characters)",first));form.add(Ui.formField("Confirm new password",confirm));JScrollPane scroll=new JScrollPane(form,ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);scroll.setPreferredSize(new Dimension(390,170));scroll.getVerticalScrollBar().setUnitIncrement(16);int result=JOptionPane.showConfirmDialog(this,scroll,"Reset password for "+email,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(result!=JOptionPane.OK_OPTION)return;char[] password=first.getPassword(),repeat=confirm.getPassword();try{if(password.length<8||password.length>100)throw new IllegalArgumentException("Password must be between 8 and 100 characters.");if(!Arrays.equals(password,repeat))throw new IllegalArgumentException("The passwords do not match.");frame.accountDao().resetUserPassword(email,password);Ui.info(this,"Password reset. The passenger can now sign in with this email and the new password.");}catch(Exception ex){Ui.error(this,ex.getMessage());}finally{Arrays.fill(password,'\0');Arrays.fill(repeat,'\0');}}
}
